css:
@page {
    size: A4;
    margin: 0 !important;
}

body {
    margin: 0 !important;
    padding: 0 !important;
    font-family: "Times New Roman", serif;
    font-size: 15px;
    line-height: 1.4;
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
}

.page {
    position: relative;
    width: 210mm;
    height: 297mm;
    margin: 0 auto;
    overflow: hidden;
}

/* Background Image */
.page img.bg {
    position: absolute;
    top: 0;
    left: 0;
    width: 210mm;
    height: 297mm;
    object-fit: cover;
    z-index: 1;
}

/* CONTENT */
.page .content {
    position: absolute;
    top: 48mm; /* <<<<<< Adjust this based on letterhead height */
    left: 0;
    width: 100%;
    padding: 0 20mm; /* side padding */
    z-index: 2;
    box-sizing: border-box;
    text-align: justify;
}

/* Text styling */
.content h2 {
    margin: 0 0 10px 0;
    font-size: 20px;
    font-weight: bold;
    text-align: center;
}

.content p {
    margin: 0 0 12px 0;
    font-size: 15px;
    text-indent: 30px;
}

.details p {
    text-indent: 0;
    margin: 0 0 8px 0;
}

.signature {
    margin-top: 40px;
    font-size: 15px;
    font-weight: bold;
}
